"""Restore deterministic reviewed CSV/parquet exports without a network call.
The compressed payload contains only project-derived datasets and metadata.
Regenerate the scientific outputs with python src/pipeline.py.
"""
from pathlib import Path
import base64,io,tarfile
PAYLOAD = ""
def restore(root=None):
    root = Path(root) if root else Path(__file__).resolve().parents[1]
    with tarfile.open(fileobj=io.BytesIO(base64.b64decode(PAYLOAD)),mode='r:gz') as archive:
        for item in archive.getmembers():
            dest=(root/item.name).resolve()
            if not dest.is_relative_to(root.resolve()) or not item.isfile():
                raise ValueError('Unsafe bundled archive member')
            dest.parent.mkdir(parents=True,exist_ok=True)
            dest.write_bytes(archive.extractfile(item).read())
if __name__ == '__main__': restore()
